import Foundation
import Testing

/// Loads fixture JSON files from the `Fixtures/` directory bundled with the test target.
enum FixtureLoader {
    /// Returns the URL of the named fixture file (e.g. `"artifact.json"`).
    static func url(for name: String) throws -> URL {
        // The test target bundles the Fixtures directory as a resource.
        // Bundle.module is generated by SPM for test targets with resources.
        guard
            let url = Bundle.module.url(
                forResource: name, withExtension: nil, subdirectory: "Fixtures")
        else {
            Issue.record("Fixture not found: Fixtures/\(name)")
            throw FixtureError.notFound(name)
        }
        return url
    }

    /// Loads and returns the raw `Data` from a named fixture file.
    static func data(for name: String) throws -> Data {
        let url = try url(for: name)
        return try Data(contentsOf: url)
    }

    enum FixtureError: Error {
        case notFound(String)
    }
}
